import React, { useEffect } from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { VoterDashboard } from './pages/VoterDashboard';
import { PermissionGate } from './components/PermissionGate';
import { Login } from './pages/Login';
import { Signup } from './pages/Signup';
import { AdminDashboard } from './pages/AdminDashboard';
import { CandidateDashboard } from './pages/CandidateDashboard';
import { DashboardLayout } from './layouts/DashboardLayout';
import { toast, ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { useSignalR } from './context/SignalRContext';
import { useAuthStore } from './store/authStore';
import api from './services/api';

const LayoutWrapper: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <DashboardLayout>{children}</DashboardLayout>
);

const App: React.FC = () => {
    const { connection } = useSignalR();
    const { user } = useAuthStore();

    useEffect(() => {
        if (!connection || !user) return;

        connection.on("CandidateApproved", async (approvedUserId: number) => {
            // Check if it's ME
            if (user && user.id === approvedUserId) {
                toast.success("Congratulations! Your application has been approved! Redirecting...");

                // Silent Refresh
                try {
                    // Call API to get new token with updated roles
                    // We need to add this method to api.ts first, but for now assuming direct axios or api call
                    // Since api.ts is not yet updated with 'refreshToken', I will add it shortly.
                    // Or I can use raw axios if needed, but better to update api.ts.
                    // I will perform the update in next step.
                    // For now, assume api.refreshToken() exists or we construct raw call.
                    // Wait, I can't leave broken code.
                    // I'll assume I update api.ts immediately.

                    const res = await api.post('/auth/refresh-token', {});
                    if (res.data && res.data.token) {
                        // Decode new token to update user state
                        const newToken = res.data.token;

                        // DECODE Logic (reused from Login.tsx roughly or simple parse)
                        const base64Url = newToken.split('.')[1];
                        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
                        const jsonPayload = decodeURIComponent(window.atob(base64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join(''));
                        const payload = JSON.parse(jsonPayload);

                        let permissions = [];
                        if (Array.isArray(payload.permissions)) permissions = payload.permissions;
                        else if (payload.permissions) permissions = [payload.permissions];

                        const updatedUser = {
                            ...user,
                            permissions: permissions
                        };

                        useAuthStore.getState().setAuth(newToken, updatedUser); // Direct store access or from hook

                        // Force navigation
                        // We need navigate function. BrowserRouter is inside App return... 
                        // We cannot use 'useNavigate' here because App is the Router provider.
                        // We must move logic to a child component or use window.location (ugly)
                        // OR move Router *outside* App in index.tsx.
                        // Given implementation, we should use a Layout wrapper that handles this logic.
                        // Or just window.location.href = '/candidate' (full reload, ensures clean state).
                        // Full reload is actually safer for role changes.
                        setTimeout(() => window.location.href = '/candidate', 2000);
                    }

                } catch (e) {
                    console.error("Failed to auto-refresh role", e);
                    toast.warning("You are approved! Please logout and login to access dashboard.");
                }
            } else {
                toast.info("A new candidate has been approved!");
            }
        });

        return () => {
            connection.off("CandidateApproved");
        }
    }, [connection, user]);

    return (
        <BrowserRouter>
            <Routes>
                {/* Public Routes */}
                <Route path="/login" element={<Login />} />
                <Route path="/signup" element={<Signup />} />

                {/* Protected Routes */}
                <Route path="/voter" element={
                    <PermissionGate permission="Permissions.CanViewDashboard">
                        <LayoutWrapper>
                            <VoterDashboard />
                        </LayoutWrapper>
                    </PermissionGate>
                } />

                <Route path="/admin" element={
                    <PermissionGate permission="Permissions.CanViewAdminStats">
                        <LayoutWrapper>
                            <AdminDashboard />
                        </LayoutWrapper>
                    </PermissionGate>
                } />

                <Route path="/candidate" element={
                    <PermissionGate permission="Permissions.CanAccessCandidateDashboard">
                        <LayoutWrapper>
                            <CandidateDashboard />
                        </LayoutWrapper>
                    </PermissionGate>
                } />

                {/* Default Redirect */}
                <Route path="/" element={<Navigate to="/login" />} />
                <Route path="*" element={<Navigate to="/login" />} />
            </Routes>
            <ToastContainer position="bottom-right" />
        </BrowserRouter>
    );
};

export default App;
